DROP ALL OBJECTS;
CREATE TABLE business(id BIGINT PRIMARY KEY,business_type VARCHAR(16),deleted_at TIMESTAMP NULL);
CREATE TABLE file_resource(id BIGINT PRIMARY KEY,public_url VARCHAR(1024),status VARCHAR(16),deleted_at TIMESTAMP NULL);
CREATE TABLE business_travel_car(id BIGINT AUTO_INCREMENT PRIMARY KEY,business_id BIGINT,model VARCHAR(128),seat_num INT,description VARCHAR(500),image_resource_id BIGINT,status VARCHAR(16),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL);
CREATE TABLE business_hotel_room(id BIGINT AUTO_INCREMENT PRIMARY KEY,business_id BIGINT,name VARCHAR(128),bed_spec VARCHAR(128),description VARCHAR(500),image_resource_id BIGINT,status VARCHAR(16),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL);
CREATE TABLE business_food_dish(id BIGINT AUTO_INCREMENT PRIMARY KEY,business_id BIGINT,name VARCHAR(128),description VARCHAR(500),is_recommended BOOLEAN NOT NULL DEFAULT FALSE,image_resource_id BIGINT,sort_no INT,status VARCHAR(16),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL);
